<?php require 'config.php'; $active='tours';$title='Khám phá tour — TourVela';$q=trim($_GET['q']??'');$dur=$_GET['duration']??'';$tours=[];$err='';try{$sql="SELECT t.*,d.TenDiaDiem FROM tours t LEFT JOIN diadiem d ON d.MaDiaDiem=t.MaDiaDiem WHERE t.TrangThai='dang_mo'";$p=[];if($q!==''){$sql.=" AND (t.TenTour LIKE ? OR d.TenDiaDiem LIKE ? OR d.TinhThanh LIKE ?)";$p=["%$q%","%$q%","%$q%"];}if($dur==='1-2')$sql.=" AND t.SoNgay BETWEEN 1 AND 2";if($dur==='3-4')$sql.=" AND t.SoNgay BETWEEN 3 AND 4";if($dur==='5+')$sql.=" AND t.SoNgay>=5";$st=db()->prepare($sql." ORDER BY t.MaTour DESC");$st->execute($p);$tours=$st->fetchAll();}catch(Throwable $e){$err='Chưa kết nối cơ sở dữ liệu. Hãy nhập database.sql theo README.';}require 'includes/header.php';?>
<section class="pagehero"><div class="eyebrow light">● MỘT THẾ GIỚI ĐANG CHỜ</div><h1>Tìm hành trình<br><em>của riêng bạn.</em></h1><p>Những cung đường đáng nhớ, những trải nghiệm không thể sao chép.</p></section><section class="section"><div class="sectionhead"><div><div class="eyebrow">● BỘ SƯU TẬP HÀNH TRÌNH</div><h2><?=$q?'Kết quả tìm kiếm':'Tất cả tour'} <em><?=$q?'“'.e($q).'”':'đang mở bán.'?></em></h2></div><span><?=count($tours)?> hành trình</span></div><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Tên tour hoặc điểm đến..."><select name="duration"><option value="">Mọi thời lượng</option><option value="1-2" <?=$dur==='1-2'?'selected':''?>>1–2 ngày</option><option value="3-4" <?=$dur==='3-4'?'selected':''?>>3–4 ngày</option><option value="5+" <?=$dur==='5+'?'selected':''?>>5 ngày trở lên</option></select><button class="btn dark">Lọc hành trình ↗</button></form><?php if($err):?><div class="notice"><?=$err?></div><?php endif;?><div class="cards"><?php foreach($tours as $t):?><article class="card"><a class="cardimg" href="tour-detail.php?id=<?=(int)$t['MaTour']?>"><img src="<?=e($t['AnhDaiDien'])?>" alt=""><span><?=e($t['TenDiaDiem']??'Việt Nam')?></span></a><div class="cardbody"><small>◷ <?=(int)$t['SoNgay']?> ngày <?=(int)$t['SoDem']?> đêm <i>★ 4.9</i></small><h3><a href="tour-detail.php?id=<?=(int)$t['MaTour']?>"><?=e($t['TenTour'])?></a></h3><div class="price"><span><small>Giá từ</small><b><?=money($t['GiaTour'])?></b></span><a class="circle" href="tour-detail.php?id=<?=(int)$t['MaTour']?>">↗</a></div></div></article><?php endforeach;?></div><?php if(!$tours&&!$err):?><div class="empty"><h3>Chưa tìm thấy hành trình phù hợp</h3><p>Thử từ khoá khác hoặc xem tất cả tour.</p><a class="btn dark" href="tours.php">Xem tất cả tour ↗</a></div><?php endif;?></section><?php require 'includes/footer.php';?>
